INSERT INTO question(id,quiz_id,question_type_id,prompt,explanation,position) VALUES ('3e186854-c79a-b881-5b9a-03649f9b4275','bf3de2e3-58fa-a6b4-433e-e29e15b810a0','3','Seeing little vegetation proves that a surface is currently hot.','Visible plant cover is an observation; present heat and eruption timing require other evidence.','2') ON CONFLICT DO NOTHING;
